export type DebtTipo = 'Deuda' | 'Abono';
export type DebtEstado = '' | 'Saldado';

export interface HouseholdDebt {
  id: string;
  householdId: string;
  concept: string;
  tipo: DebtTipo;
  amount: number;
  debtor: string;
  category: string;
  date: Date;
  registeredBy: string;
  estado: DebtEstado;
  saldaId: string | null;
  notas: string;
  cruzado: boolean;
  /** Set when this debt was auto-generated by splitting a HouseholdExpense. */
  expenseId?: string | null;
  /** Agreed payment deadline for this debt. Omitted/null = open-ended, no fixed date. */
  dueDate?: Date | null;
  createdAt: Date;
}

export type NewHouseholdDebt = Omit<HouseholdDebt, 'id' | 'createdAt'>;
